const{GRADES,TYPES,TYPE_STRONG,ABILITIES,MONSTERS,XION_BOSS,MOVES,MOVE_SETS,DUNGEONS,ACHIEVEMENTS}=window.GAME_DATA;
const STAT_LABELS=['HP','공격','방어','특수공격','특수방어','스피드'];
const ENEMY_SUSTAIN_MULTIPLIER=.25;
const defaultSave={owned:{f1:1},sound:true,best:0,achievements:{},records:{wins:0,clears:0,captures:0}};
let save=loadSave(),run=null,busy=false,filter='all',audioCtx,pendingDungeon=null,selectedMonster=null;

function loadSave(){try{const x=JSON.parse(localStorage.getItem('seongjimon-save')||'{}');return{...defaultSave,...x,owned:{...defaultSave.owned,...(x.owned||{})},achievements:x.achievements||{},records:{...defaultSave.records,...(x.records||{})}}}catch{return structuredClone(defaultSave)}}
function persist(){localStorage.setItem('seongjimon-save',JSON.stringify(save));updateHeader()}
function updateHeader(){document.querySelector('#best-count').textContent=save.best;document.querySelector('#owned-count').textContent=Object.keys(save.owned).length;document.querySelector('#achievement-count').textContent=Object.keys(save.achievements).length;document.querySelector('#sound-toggle').textContent=save.sound?'♪':'×'}
function grade(m){return GRADES[m.g]}function ability(m){return ABILITIES[m.ability]}function type(id){return TYPES.find(t=>t.id===id)}
function typeBadges(m){return m.types.map(id=>`<span class="type-badge" style="--type-color:${type(id).color}">${type(id).name}</span>`).join('')}
function figureClass(m){return`monster-figure shape-${m.shape} grade-${grade(m).id}`}
function show(screen){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.querySelector(`#screen-${screen}`).classList.add('active');document.querySelectorAll('.dock button').forEach(b=>b.classList.toggle('active',b.dataset.go===screen));if(screen==='collection')renderCollection();if(screen==='dungeons')renderDungeons();if(screen==='achievements')renderAchievements();tone(260,.05)}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(el.t);el.t=setTimeout(()=>el.classList.remove('show'),2400)}
function tone(freq=300,d=.08,wave='sine'){if(!save.sound)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=wave;o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d)}catch{}}
function wait(ms){return new Promise(r=>setTimeout(r,ms))}
function shuffle(a){return[...a].sort(()=>Math.random()-.5)}

function renderDungeons(){document.querySelector('#dungeon-grid').innerHTML=DUNGEONS.map(d=>`<button class="dungeon-card" style="--dungeon-color:${d.color}" data-dungeon="${d.id}"><span class="difficulty">${d.difficulty}</span><h3>${d.name}</h3><p>${d.desc}</p><div class="dungeon-meta"><span>${d.floors}구역</span><span>조우 지냄 포획 가능</span><span>${GRADES[d.maxG].label}까지</span></div></button>`).join('')}
function openTeamSelect(dungeonId){pendingDungeon=DUNGEONS.find(d=>d.id===dungeonId);selectedMonster=null;document.querySelector('#team-dungeon-info').textContent=`${pendingDungeon.name} · ${pendingDungeon.difficulty} · ${pendingDungeon.floors}구역`;renderTeam();show('team')}
function renderTeam(){const owned=MONSTERS.filter(m=>save.owned[m.id]);document.querySelector('#team-grid').innerHTML=owned.map(m=>`<button class="team-card ${selectedMonster===m.id?'selected':''}" data-team="${m.id}"><span style="color:${grade(m).color};font-size:.62rem;font-weight:900">${grade(m).label.toUpperCase()} · ${m.form}</span><div class="${figureClass(m)}"><i class="face-dot left"></i><i class="face-dot right"></i></div><div class="type-row">${typeBadges(m)}</div><h3>${m.name}</h3><div class="mini-stats"><span>HP ${m.stats[0]}</span><span>공격 ${m.stats[1]}</span><span>특공 ${m.stats[3]}</span><span>스피드 ${m.stats[5]}</span></div></button>`).join('');const chosen=MONSTERS.find(m=>m.id===selectedMonster);document.querySelector('#selected-summary').textContent=chosen?`${chosen.name} · ${ability(chosen).name}`:'출전할 지냄을 선택해라.';document.querySelector('#confirm-team').disabled=!chosen}
function selectTeam(id){selectedMonster=id;renderTeam()}

function movesFor(m){const set=[...MOVE_SETS[m.g]];if(m.variant===4)set[0]='pierce';if(m.variant===5)set[1]=m.g>2?'dimension':'compress';return set.map(id=>({id,...MOVES[id]}))}
function statValue(base,level,scale=1){return Math.round((base+level*2)*scale)}
function makeFighter(monster,level,scale=1){const s=monster.stats,maxHp=Math.round((s[0]*1.55+level*4)*scale),moves=movesFor(monster);return{...monster,level,maxHp,hp:maxHp,attack:statValue(s[1],level,scale),defense:statValue(s[2],level,scale),specialAttack:statValue(s[3],level,scale),specialDefense:statValue(s[4],level,scale),speed:statValue(s[5],level,scale),mods:{atk:1,def:1,spa:1,spd:1,spe:1,acc:0},dot:0,dotTurns:0,stun:0,shield:0,traitUsed:false,endureUsed:false,lastMove:null,moves,pp:Object.fromEntries(moves.map(x=>[x.id,x.pp]))}}
function startRun(){if(!pendingDungeon||!selectedMonster)return;const base=MONSTERS.find(m=>m.id===selectedMonster),player=makeFighter(base,10,1);run={dungeon:pendingDungeon,floor:1,wins:0,captures:0,captureBonus:0,luck:base.ability==='fortune'?18:0,ppBonus:0,player,enemy:null,noDamage:true,captureTried:false};show('battle');nextBattle()}
function pickEnemy(){const d=run.dungeon;if(d.id==='xion'&&run.floor===d.floors)return XION_BOSS;if(run.floor===d.floors){const bosses=MONSTERS.filter(m=>m.g===d.maxG);return bosses[Math.floor(Math.random()*bosses.length)]}const ceiling=Math.min(d.maxG,d.minG+Math.floor((run.floor/d.floors)*(d.maxG-d.minG+1))),pool=MONSTERS.filter(m=>m.g>=d.minG&&m.g<=ceiling);return pool[Math.floor(Math.random()*pool.length)]}
function nextBattle(){busy=false;const base=pickEnemy(),level=9+run.floor+base.g,scale=run.dungeon.scale;run.enemy=makeFighter(base,level,scale);run.player.level=10+run.floor;run.player.traitUsed=false;run.player.endureUsed=false;run.player.moves=movesFor(run.player);run.player.pp=Object.fromEntries(run.player.moves.map(x=>[x.id,x.pp+run.ppBonus]));run.enemy.traitUsed=false;run.captureTried=false;run.noDamage=true;renderBattle();log(base.boss?`XION 심층 최종 구역. 최종보스 성지온이 나타났다!`:`${run.dungeon.name} ${run.floor}구역. 적의 HP를 낮추면 포획하기 쉬워진다.`)}
function renderBattle(){setCombatant('player',run.player);setCombatant('enemy',run.enemy);document.querySelector('#floor-label').textContent=`${run.dungeon.name} · ${run.floor}/${run.dungeon.floors}구역`;document.querySelector('#run-captures').textContent=run.captures;const pips=document.querySelector('#floor-pips');pips.innerHTML='';for(let i=1;i<=run.dungeon.floors;i++){const x=document.createElement('i');if(i<run.floor)x.className='done';if(i===run.floor)x.className='current';pips.append(x)}renderMoves();renderCapture()}
function setCombatant(side,m){document.querySelector(`#${side}-grade`).textContent=m.boss?'FINAL BOSS · XION':grade(m).label.toUpperCase();document.querySelector(`#${side}-name`).textContent=m.name;document.querySelector(`#${side}-types`).innerHTML=typeBadges(m);document.querySelector(`#${side}-ability`).textContent=`특성 · ${ability(m).name} — ${ability(m).desc}`;document.querySelector(`#${side}-level`).textContent=`Lv.${m.level}`;const fig=document.querySelector(`#${side}-figure`);fig.className=figureClass(m);fig.innerHTML='<span class="face-dot left"></span><span class="face-dot right"></span>';setHp(side,m);renderStatus(side,m)}
function setHp(side,m){const pct=Math.max(0,m.hp/m.maxHp*100),bar=document.querySelector(`#${side}-hp`);bar.style.width=`${pct}%`;bar.style.background=pct<25?'#ff5468':pct<55?'#ffd15c':'#c6ff4a';document.querySelector(`#${side}-hp-text`).textContent=`${Math.max(0,Math.round(m.hp))} / ${m.maxHp}`}
function renderStatus(side,m){const tags=[];if(m.mods.atk>1)tags.push(['공격↑','good']);if(m.mods.atk<1)tags.push(['공격↓','bad']);if(m.mods.spa>1)tags.push(['특공↑','good']);if(m.mods.def<1)tags.push(['방어↓','bad']);if(m.mods.spd<1)tags.push(['특방↓','bad']);if(m.mods.acc<0)tags.push(['명중↓','bad']);if(m.mods.spe>1)tags.push(['스피드↑','good']);if(m.shield>0)tags.push([`보호막 ${Math.round(m.shield)}`,'good']);if(m.dotTurns>0)tags.push([`잔향침식 ${m.dotTurns}턴`,'bad']);if(m.stun>0)tags.push(['행동 봉쇄','bad']);document.querySelector(`#${side}-status`).innerHTML=tags.map(t=>`<span class="${t[1]}">${t[0]}</span>`).join('')}
function effectivenessInfo(move){if(!move.power||!run?.enemy)return null;const mult=typeMultiplier(move.type,run.enemy.types),key=String(mult).replace('.',''),labels={4:'악취가 끔찍함',2:'악취가 지독함',1:'맡을 만 함',.5:'향기로움',.25:'아름다움'};return{mult,label:labels[mult]||'맡을 만 함',cls:`effect-${key}`}}
function renderMoves(){const grid=document.querySelector('#move-grid');grid.innerHTML='';run.player.moves.forEach((m,i)=>{const pp=run.player.pp[m.id],max=m.pp+run.ppBonus,b=document.createElement('button'),effect=effectivenessInfo(m);b.className=`move-button ${pp<=0?'pp-empty':''}`;b.disabled=busy||pp<=0;b.innerHTML=`<span><strong>${m.name}</strong><small>${m.desc}</small><span class="move-meta" style="color:${type(m.type).color}">${type(m.type).name} · ${m.category==='physical'?'물리':m.category==='special'?'특수':'변화'} · 명중 ${m.acc}%</span>${effect?`<span class="effectiveness ${effect.cls}">${effect.label} (${effect.mult===.5?'1/2':effect.mult===.25?'1/4':effect.mult}배)</span>`:''}</span><b>${m.power?`위력 ${m.power}`:'변화기'}<br>PP ${pp}/${max}</b>`;b.onclick=()=>chooseMove(m,i);grid.append(b)});renderCapture()}
function captureChance(){if(!run?.enemy||run.enemy.boss)return 0;const hpFactor=1-run.enemy.hp/run.enemy.maxHp;return Math.max(.08,Math.min(.92,.2+hpFactor*.65-run.enemy.g*.04+run.captureBonus/100))}
function renderCapture(){if(!run?.enemy)return;const button=document.querySelector('#capture-button'),hint=document.querySelector('#capture-hint'),owned=!!save.owned[run.enemy.id];button.disabled=busy||run.captureTried||run.enemy.boss;if(run.enemy.boss){button.textContent='◉ 포획 불가';hint.textContent='최종보스 성지온은 포획할 수 없다.'}else if(run.captureTried){button.textContent='◉ 이번 조우 시도 완료';hint.textContent='한 번의 조우에서 포획은 한 번만 시도할 수 있다.'}else{const chance=Math.round(captureChance()*100);button.textContent=`◉ ${owned?'재포획':'포획'} 시도 · ${chance}%`;hint.textContent=owned?`이미 등록된 지냄도 재포획할 수 있다 · 현재 성공률 ${chance}%`:`현재 성공률 ${chance}% · HP가 낮을수록 성공률이 올라간다.`}}
function log(t){document.querySelector('#battle-log').textContent=t}
function animate(side,cls){const f=document.querySelector(`#${side}-figure`);f.classList.remove(cls);void f.offsetWidth;f.classList.add(cls);setTimeout(()=>f.classList.remove(cls),450)}
function heal(actor,amount){const before=actor.hp;actor.hp=Math.min(actor.maxHp,actor.hp+Math.round(amount));return Math.round(actor.hp-before)}
function combatHeal(actor,amount,side){return heal(actor,amount*(side==='enemy'?ENEMY_SUSTAIN_MULTIPLIER:1))}
function addShield(actor,amount,side){const gained=Math.round(amount*(side==='enemy'?ENEMY_SUSTAIN_MULTIPLIER:1));actor.shield+=gained;return gained}
function effectiveSpeed(a){return a.speed*a.mods.spe}
function typeMultiplier(moveType,targetTypes){let mult=1;for(const t of targetTypes){if(TYPE_STRONG[moveType].includes(t))mult*=2;if(TYPE_STRONG[t].includes(moveType))mult*=.5}return Math.max(.25,Math.min(4,mult))}
function beginAction(actor,side){const notes=[];if(actor.ability==='renewal'){const h=combatHeal(actor,actor.maxHp*.03,side);if(h)notes.push(`${ability(actor).name} ${h} 회복`)}if(actor.dotTurns>0){actor.hp-=actor.dot;actor.dotTurns--;notes.push(`잔향침식 ${actor.dot} 피해`)}setHp(side,actor);renderStatus(side,actor);return notes}
function defendStat(target,category,move){if(move.pierce)return category==='physical'?target.defense:target.specialDefense;let value=category==='physical'?target.defense*target.mods.def:target.specialDefense*target.mods.spd;if(target.ability==='mirror')value=Math.max(target.defense*target.mods.def,target.specialDefense*target.mods.spd);return value}
function calculateDamage(attacker,target,move){const physical=move.category==='physical',off=(physical?attacker.attack*attacker.mods.atk:attacker.specialAttack*attacker.mods.spa),def=defendStat(target,move.category,move);let powerMod=1;if(attacker.ability==='diffuse')powerMod*=1.1;if(attacker.ability==='resonance'&&attacker.lastMove===move.id)powerMod*=1.25;if(attacker.ability==='surge'&&attacker.hp/attacker.maxHp<=.35)powerMod*=1.3;if(attacker.ability==='sovereignty')powerMod*=1.08;const stab=attacker.types.includes(move.type)||attacker.ability==='omni'?1.25:1,typeMod=typeMultiplier(move.type,target.types),critChance=.07+(attacker.ability==='critical'?.22:0)+(move.crit||0)/100,crit=Math.random()<critChance;let dmg=Math.max(2,Math.round((((2*attacker.level/5+2)*move.power*off/Math.max(1,def))/50+2)*powerMod*stab*typeMod*(.87+Math.random()*.14)*(crit?1.5:1)));if(target.ability==='veil'&&!target.traitUsed){dmg=Math.round(dmg*.65);target.traitUsed=true}if(target.ability==='bastion'&&target.hp===target.maxHp&&!target.traitUsed){dmg=Math.round(dmg*.4);target.traitUsed=true}if(target.ability==='armor')dmg=Math.round(dmg*.92);if(target.ability==='sovereignty')dmg=Math.round(dmg/1.08);const blocked=Math.min(target.shield,dmg);target.shield-=blocked;dmg-=blocked;let endured=false;if(target.hp-dmg<=0&&target.ability==='endure'&&!target.endureUsed){dmg=Math.max(0,target.hp-1);target.endureUsed=true;endured=true}target.hp-=dmg;return{dmg,blocked,crit,typeMod,endured}}
function applyEffect(attacker,target,move,side){if(!move.effect)return'';const chance=Math.min(100,(move.chance||100)+(attacker.ability==='conductor'?20:0));if(Math.random()*100>chance)return' 부가효과는 발동하지 않았다.';switch(move.effect){case'accuracy':target.mods.acc=Math.max(-30,target.mods.acc-12);return' 상대 명중률이 내려갔다.';case'shield':{const gained=addShield(attacker,24+attacker.g*5,side);return` 보호막 ${gained}을 생성했다.`}case'rest':{const h=combatHeal(attacker,attacker.maxHp*.35,side);attacker.mods.def=Math.max(.65,attacker.mods.def*.82);return` ${h} 회복했지만 방어가 내려갔다.`}case'attackDown':target.mods.atk=Math.max(.6,target.mods.atk*.84);return' 상대 공격이 내려갔다.';case'healShield':{const h=combatHeal(attacker,attacker.maxHp*.22,side),gained=addShield(attacker,20+attacker.g*4,side);return` ${h} 회복하고 보호막 ${gained}을 생성했다.`}case'specialUp':attacker.mods.spa=Math.min(1.75,attacker.mods.spa*1.18);return' 자신의 특수공격이 올랐다.';case'specialDefenseDown':target.mods.spd=Math.max(.55,target.mods.spd*.76);return' 상대 특수방어가 크게 내려갔다.';case'dot':target.dot=8+attacker.g*3;target.dotTurns=3;return' 상대가 3턴간 잔향침식 상태가 됐다.';case'stun':target.stun=1;return' 상대의 다음 행동을 봉쇄했다.';case'dispel':target.shield=0;target.mods.atk=Math.min(1,target.mods.atk);target.mods.spa=Math.min(1,target.mods.spa);target.mods.def=Math.min(1,target.mods.def);target.mods.spd=Math.min(1,target.mods.spd);return' 상대 보호막과 강화를 제거했다.';default:return''}}
function checkSurvival(actor){if(actor.hp<=0&&actor.ability==='endure'&&!actor.endureUsed){actor.hp=1;actor.endureUsed=true;return true}return actor.hp>0}
async function performAction(actor,target,move,aSide,tSide){const start=beginAction(actor,aSide);if(!checkSurvival(actor))return start.join(' · ');if(actor.stun>0){actor.stun--;renderStatus(aSide,actor);return`${start.length?start.join(' · ')+'. ':''}${actor.name}의 행동이 봉쇄됐다.`}if(move.power&&target.ability==='ghoststep'&&!target.traitUsed){target.traitUsed=true;actor.lastMove=move.id;return`${move.name}! ${ability(target).name}으로 공격을 완전히 회피했다.`}const dodge=target.ability==='phase'?15:0,hitChance=Math.max(30,move.acc+actor.mods.acc-dodge);if(Math.random()*100>hitChance){actor.lastMove=move.id;if(actor.ability==='reflux'){const h=combatHeal(actor,actor.maxHp*.08,aSide);setHp(aSide,actor);return`${move.name}은 빗나갔다. ${ability(actor).name}으로 ${h} 회복했다.`}return`${move.name}은 빗나갔다.`}animate(aSide,'attack');tone(aSide==='player'?370:150,.12,aSide==='player'?'sawtooth':'square');await wait(230);let text=`${move.name}!`;if(move.power){const r=calculateDamage(actor,target,move);animate(tSide,'hit');text+=` ${r.dmg} 피해${r.crit?' · 치명타!':''}${r.typeMod>1.01?' · 효과가 굉장했다!':r.typeMod<.99?' · 효과가 약했다.':''}${r.blocked?` · 보호막 ${r.blocked} 흡수`:''}${r.endured?' · 차원 고정점으로 버텼다':''}.`;if(aSide==='player'&&r.typeMod>1.01)unlock('super_hit');if(tSide==='player'&&r.dmg>0)run.noDamage=false;if(move.drain){const h=combatHeal(actor,r.dmg*move.drain,aSide);text+=` ${h} 흡수.`}if(actor.ability==='absorb'){const h=combatHeal(actor,r.dmg*.15,aSide);if(h)text+=` ${ability(actor).name}으로 ${h} 회복.`}}text+=applyEffect(actor,target,move,aSide);if(move.recoil){const recoil=Math.max(1,Math.round(actor.maxHp*move.recoil));actor.hp-=recoil;text+=` 반동 ${recoil} 피해.`}actor.lastMove=move.id;setHp(aSide,actor);setHp(tSide,target);renderStatus(aSide,actor);renderStatus(tSide,target);return start.length?`${start.join(' · ')}. ${text}`:text}
function hasUsableMove(){return run.player.moves.some(m=>(run.player.pp[m.id]||0)>0)}
function exitForNoPP(){save.best=Math.max(save.best,run.floor);checkProgressAchievements();persist();document.querySelector('#result-floor').textContent=`${run.dungeon.name} ${run.floor}구역 · PP 소진`;finishResult();toast('모든 기술의 PP가 소진되어 원정에서 복귀했다.')}
async function chooseMove(move,index){if(busy||run.player.pp[move.id]<=0)return;busy=true;run.player.pp[move.id]--;const enemyChoices=run.enemy.moves.filter(m=>run.enemy.pp[m.id]>0),enemyMove=enemyChoices.length?enemyChoices[Math.floor(Math.random()*enemyChoices.length)]:{id:'trace',...MOVES.trace};if(run.enemy.pp[enemyMove.id]!=null)run.enemy.pp[enemyMove.id]--;renderMoves();const playerFirst=effectiveSpeed(run.player)>=effectiveSpeed(run.enemy),order=playerFirst?[[run.player,run.enemy,move,'player','enemy'],[run.enemy,run.player,enemyMove,'enemy','player']]:[[run.enemy,run.player,enemyMove,'enemy','player'],[run.player,run.enemy,move,'player','enemy']];const logs=[];for(const action of order){if(action[0].hp<=0||action[1].hp<=0)break;logs.push(await performAction(...action));log(logs.join(' / '));await wait(420)}if(run.enemy.hp<=0){if(run.player.pp[move.id]===0)unlock('pp_master');winBattle();return}if(run.player.hp<=0){gameOver();return}if(!hasUsableMove()){exitForNoPP();return}busy=false;renderMoves()}

async function enemyCounterAfterCaptureFail(){const choices=run.enemy.moves.filter(m=>run.enemy.pp[m.id]>0),move=choices.length?choices[Math.floor(Math.random()*choices.length)]:{id:'trace',...MOVES.trace};if(run.enemy.pp[move.id]!=null)run.enemy.pp[move.id]--;const text=await performAction(run.enemy,run.player,move,'enemy','player');log(`포획 실패! ${text}`);if(run.enemy.hp<=0){winBattle();return}if(run.player.hp<=0){gameOver();return}busy=false;renderMoves()}
async function attemptCapture(){if(busy||run.captureTried||run.enemy.boss)return;busy=true;run.captureTried=true;const chance=captureChance(),wasOwned=!!save.owned[run.enemy.id];renderMoves();log(`${run.enemy.name} ${wasOwned?'재포획을':'포획을'} 시도한다...`);tone(440,.18,'sine');await wait(650);if(Math.random()<chance){save.owned[run.enemy.id]=1;save.records.captures++;run.captures++;unlock('first_capture');checkProgressAchievements();persist();document.querySelector('#run-captures').textContent=run.captures;log(`${run.enemy.name} ${wasOwned?'재포획':'포획'} 성공! ${wasOwned?'포획 기록을 추가했다.':'도감에 등록했다.'}`);tone(720,.32,'sawtooth');setTimeout(()=>winBattle(true),800);return}await enemyCounterAfterCaptureFail()}

function rewardQuality(){const score=Math.random()*100+run.dungeon.index*10+(run.floor/run.dungeon.floors)*22+run.luck;if(score>=128)return{n:3,id:'legend',name:'LEGENDARY'};if(score>=103)return{n:2,id:'epic',name:'EPIC'};if(score>=78)return{n:1,id:'rare',name:'RARE'};return{n:0,id:'common',name:'COMMON'}}
function rewardPool(q){const n=q.n;return[
 {id:'heal',icon:'✚',name:'고농도 회복',desc:`HP ${30+n*12}% 회복`,apply:()=>heal(run.player,run.player.maxHp*(.30+n*.12))},
 {id:'atk',icon:'⚔',name:'물리 농축',desc:`공격 ${8+n*4}% 강화`,apply:()=>run.player.mods.atk*=1.08+n*.04},
 {id:'spa',icon:'✦',name:'특수 잔향 증폭',desc:`특수공격 ${8+n*4}% 강화`,apply:()=>run.player.mods.spa*=1.08+n*.04},
 {id:'def',icon:'⬡',name:'기하 외벽',desc:`방어·특수방어 ${7+n*3}% 강화`,apply:()=>{run.player.mods.def*=1.07+n*.03;run.player.mods.spd*=1.07+n*.03}},
 {id:'speed',icon:'»',name:'순풍 발향',desc:`스피드 ${10+n*5}% 강화`,apply:()=>run.player.mods.spe*=1.1+n*.05},
 {id:'hp',icon:'♥',name:'용기 확장',desc:`최대 HP ${10+n*8} 증가`,apply:()=>{run.player.maxHp+=10+n*8;run.player.hp+=10+n*8}},
 {id:'pp',icon:'▣',name:'PP 확장 결정',desc:`남은 원정 동안 구역별 최대 PP +${1+n}`,apply:()=>run.ppBonus+=1+n},
 {id:'capture',icon:'◉',name:'포획 감응',desc:`남은 원정 포획률 +${4+n*3}%`,apply:()=>run.captureBonus+=4+n*3},
 {id:'shield',icon:'◉',name:'잔향 방벽',desc:`다음 구역 보호막 ${28+n*15}`,apply:()=>run.player.shield+=28+n*15},
 {id:'luck',icon:'☄',name:'행운의 냄새결정',desc:`이번 원정 보상 운 +${10+n*5}`,apply:()=>run.luck+=10+n*5},
 ...(n>=2?[{id:'full',icon:'★',name:'완전 재구성',desc:'HP 완전 회복·능력 하락 제거',apply:()=>{run.player.hp=run.player.maxHp;Object.keys(run.player.mods).forEach(k=>{if(k!=='acc')run.player.mods[k]=Math.max(1,run.player.mods[k])});run.player.mods.acc=Math.max(0,run.player.mods.acc)}}]:[])
 ]}
function showRewards(){const q=rewardQuality(),choices=shuffle(rewardPool(q)).slice(0,3);document.querySelector('#reward-quality').className=`eyebrow reward-tier-${q.id}`;document.querySelector('#reward-quality').textContent=`${q.name} REWARD`;document.querySelector('#reward-context').textContent=`${run.dungeon.difficulty} · ${run.floor}구역 · 현재 운 ${run.luck}`;const box=document.querySelector('#reward-options');box.innerHTML='';choices.forEach((r,i)=>{const b=document.createElement('button');b.className='reward-option';b.dataset.rewardIndex=i;b.innerHTML=`<b>${r.icon}</b><strong>${r.name}</strong><small>${r.desc}</small>`;b.onclick=()=>{r.apply();document.querySelector('#reward-overlay').classList.remove('active');run.floor++;nextBattle()};box.append(b)});document.querySelector('#reward-overlay').classList.add('active')}
function winBattle(captured=false){run.wins++;save.records.wins++;unlock('first_win');if(!captured)log(`${run.enemy.name} 격파!`);tone(520,.12);setTimeout(()=>{if(run.floor>=run.dungeon.floors)completeRun();else showRewards()},800)}
function completeRun(){save.records.clears++;save.best=Math.max(save.best,run.dungeon.floors);if(run.dungeon.id==='sewer')unlock('easy_clear');if(run.dungeon.id==='sky')unlock('hard_clear');if(run.dungeon.id==='xion')unlock('xion_clear');checkProgressAchievements();persist();document.querySelector('#result-floor').textContent=`${run.dungeon.name} 완주`;finishResult()}
function gameOver(){save.best=Math.max(save.best,run.floor);checkProgressAchievements();persist();document.querySelector('#result-floor').textContent=`${run.dungeon.name} ${run.floor}구역`;finishResult()}
function finishResult(){document.querySelector('#result-wins').textContent=run.wins;document.querySelector('#result-captures').textContent=run.captures;show('gameover')}
function abandon(){if(!run)return;checkProgressAchievements();persist();show('lobby');toast('원정을 종료하고 포획 기록을 보관했다.')}

function unlock(id){if(save.achievements[id])return;const a=ACHIEVEMENTS.find(x=>x.id===id);if(!a)return;save.achievements[id]=Date.now();persist();toast(`업적 달성: ${a.name}`)}
function checkProgressAchievements(){const owned=id=>!!save.owned[id],n=Object.keys(save.owned).length;if(n>=10)unlock('collector10');if(n>=36)unlock('collector36');if(n>=72)unlock('collector72');TYPES.forEach(t=>{const group=MONSTERS.filter(m=>m.types.includes(t.id));if(group.length&&group.every(m=>owned(m.id)))unlock(`type_all_${t.id}`)});GRADES.forEach((g,i)=>{const group=MONSTERS.filter(m=>m.g===i);if(group.length&&group.every(m=>owned(m.id)))unlock(`grade_all_${g.id}`)})}
function renderAchievements(){document.querySelector('#achievement-grid').innerHTML=ACHIEVEMENTS.map(a=>{const done=!!save.achievements[a.id];return`<article class="achievement-card ${done?'':'locked'}"><span class="achievement-icon">${a.icon}</span><small>${done?'달성 완료':'미달성'}</small><h3>${a.name}</h3><p>${a.desc}</p></article>`}).join('')}
function renderCollection(){const fs=document.querySelector('#grade-filters');fs.innerHTML='';[['all','전체'],...GRADES.map(g=>[g.id,g.label])].forEach(([id,label])=>{const b=document.createElement('button');b.textContent=label;b.classList.toggle('active',filter===id);b.onclick=()=>{filter=id;renderCollection()};fs.append(b)});const list=filter==='all'?MONSTERS:MONSTERS.filter(m=>grade(m).id===filter);document.querySelector('#collection-grid').innerHTML=list.map(m=>{const owned=!!save.owned[m.id];return`<article class="collection-card ${owned?'':'locked'}" data-monster="${m.id}"><small>${owned?'포획 완료':'미획득'}</small><span style="color:${grade(m).color}">${grade(m).label.toUpperCase()} · ${m.form}</span><div class="${figureClass(m)}">${owned?'<i class="face-dot left"></i><i class="face-dot right"></i>':''}</div><div class="type-row">${typeBadges(m)}</div><h3>${m.name}</h3><span class="trait">특성 · ${ability(m).name}<br>클릭해 상세정보 보기</span></article>`}).join('')}
function weaknessInfo(m){const weak=new Set(),strong=new Set();for(const attack of TYPES){const mult=typeMultiplier(attack.id,m.types);if(mult>1)weak.add(attack.name);if(mult<1)strong.add(attack.name)}return{weak:[...weak],strong:[...strong]}}
function openDetail(id){const m=MONSTERS.find(x=>x.id===id),owned=!!save.owned[id],rules=weaknessInfo(m),moves=movesFor(m);document.querySelector('#detail-content').innerHTML=`<section class="detail-hero"><span style="color:${grade(m).color};font-size:.7rem;font-weight:900">${grade(m).label.toUpperCase()} · ${m.form}</span><div class="${figureClass(m)}">${owned?'<i class="face-dot left"></i><i class="face-dot right"></i>':''}</div><div class="type-row" style="justify-content:center">${typeBadges(m)}</div><h3>${m.name}</h3><p>${m.description}</p><span class="trait">${owned?'포획 완료 · 도감 등록':'아직 포획하지 못함'}</span></section><div><section class="detail-panel"><h3>종족값 · 합계 ${m.stats.reduce((a,b)=>a+b,0)}</h3><div class="stat-list">${m.stats.map((v,i)=>`<div class="stat-line"><span>${STAT_LABELS[i]}</span><b>${v}</b><div class="stat-bar"><i style="width:${Math.min(100,v/1.8)}%"></i></div></div>`).join('')}</div></section><section class="detail-panel"><h3>특성 · ${ability(m).name}</h3><p class="section-copy">${ability(m).desc}</p></section><section class="detail-panel"><h3>타입 상성</h3><div class="detail-rule"><span>약점: ${rules.weak.join(', ')||'없음'}</span><span>내성: ${rules.strong.join(', ')||'없음'}</span></div></section><section class="detail-panel"><h3>사용 기술</h3><div class="detail-moves">${moves.map(x=>`<div class="detail-move"><strong style="color:${type(x.type).color}">${x.name} · ${type(x.type).name}</strong><small>${x.category==='physical'?'물리':x.category==='special'?'특수':'변화'} · 위력 ${x.power||'-'} · 명중 ${x.acc} · PP ${x.pp}<br>${x.desc}</small></div>`).join('')}</div></section></div>`;show('detail')}

document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go)show(go.dataset.go);const dungeon=e.target.closest('[data-dungeon]');if(dungeon)openTeamSelect(dungeon.dataset.dungeon);const team=e.target.closest('[data-team]');if(team)selectTeam(team.dataset.team);const monster=e.target.closest('[data-monster]');if(monster)openDetail(monster.dataset.monster)});
document.querySelector('#start-run').onclick=()=>show('dungeons');document.querySelector('#confirm-team').onclick=startRun;document.querySelector('#retry-run').onclick=()=>show('dungeons');document.querySelector('#abandon-run').onclick=abandon;document.querySelector('#capture-button').onclick=attemptCapture;document.querySelector('#achievements-open').onclick=()=>show('achievements');document.querySelector('#sound-toggle').onclick=()=>{save.sound=!save.sound;persist();toast(save.sound?'소리를 켰다.':'소리를 껐다.')};
checkProgressAchievements();updateHeader();renderDungeons();
window.seongjimon={openDungeons:()=>show('dungeons'),openAchievements:()=>show('achievements'),openCollection:()=>show('collection'),getStatus:()=>({captures:save.records.captures,owned:Object.keys(save.owned).length,total:MONSTERS.length,achievements:Object.keys(save.achievements).length,bestFloor:save.best,inRun:!!run,dungeon:run?.dungeon.name||null})};
if(document.modelContext?.registerTool){const tools=[{name:'read_game_status',title:'게임 상태 확인',description:'도감, 포획 기록, 업적과 원정 진행 여부를 확인한다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>window.seongjimon.getStatus()},{name:'open_dungeon_selection',title:'던전 선택 열기',description:'난이도별 던전과 출전 지냄을 선택하는 흐름을 시작한다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{show('dungeons');return{opened:true,dungeons:DUNGEONS.map(d=>d.name)}}},{name:'open_jinaem_collection',title:'지냄 도감 열기',description:'지냄의 타입, 종족값, 특성과 상세 설명을 확인하는 도감을 연다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{show('collection');return{opened:true,owned:Object.keys(save.owned).length,total:MONSTERS.length}}}];tools.forEach(tool=>{try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}})}
